"""Fault-injectable external KMS provider for end-to-end testing.

Wraps the built-in local provider under a different provider_id; a JSON
control file (FAKEPROV_CTRL) lists operations that should raise a backend
error, letting tests simulate KMS/HSM outages across processes.
"""

import json
import os

from keymgr.provider import LocalProvider

CTRL = os.environ.get("FAKEPROV_CTRL", "/tmp/fakeprov_ctrl.json")


class FakeProvider:
    provider_id = "fakekms"
    capabilities = {
        "algorithms": ["AES256", "RSA2048"],
        "operations": [
            "generate",
            "rotate",
            "import_material",
            "export_material",
            "delete",
        ],
    }

    def __init__(self):
        self._inner = LocalProvider()

    def configure(self, data_dir):
        self._inner.configure(data_dir)

    def _maybe_fail(self, op):
        try:
            with open(CTRL, "r", encoding="utf-8") as fh:
                ctrl = json.load(fh)
        except OSError:
            ctrl = {}
        if op in ctrl.get("fail", []):
            raise RuntimeError(
                "backend KMS down: handle h-SECRET material m-SECRET"
            )

    def generate(self, algorithm):
        self._maybe_fail("generate")
        return self._inner.generate(algorithm)._asdict()

    def rotate(self, algorithm):
        self._maybe_fail("rotate")
        return self._inner.rotate(algorithm)._asdict()

    def import_material(self, algorithm, public_key, material):
        self._maybe_fail("import_material")
        return self._inner.import_material(
            algorithm, public_key, material
        )._asdict()

    def export_material(self, handle):
        self._maybe_fail("export_material")
        return self._inner.export_material(handle)._asdict()

    def delete(self, handle):
        self._maybe_fail("delete")
        return self._inner.delete(handle)


def factory():
    return FakeProvider()

